local IDs = ParseCSV(RawIDsString, true)
local Names = ParseCSV(RawNamesString, false)
local Levels = ParseCSV(RawLevelsString, false)
local Zones = ParseCSV(RawZonesString, false)
local Reacts = ParseCSV(RawReactsString, false)

DP.EliteRoster = {}

-- Build the final roster and feed it to the main addon
for i = 1, #IDs do
    if Names[i] and Levels[i] then
        local rarity = Levels[i]:match("([A-Za-z%s]+)") or "Elite"
        rarity = rarity:gsub("%s+$", "") 
        local level = tonumber(Levels[i]:match("(%d+)")) or 63
        local zone = Zones[i] or "an Unknown Location"
        if zone == "-" then zone = "an Unknown Location" end

        local reactStr = Reacts[i] or "-1,-1"
        local aReact, hReact = strsplit(",", reactStr)
        local canAlliance = (aReact == "-1" or aReact == "0" or aReact == "")
        local canHorde = (hReact == "-1" or hReact == "0" or hReact == "")
        
        local validFaction = "None"
        if canAlliance and canHorde then validFaction = "Any"
        elseif canAlliance then validFaction = "Alliance"
        elseif canHorde then validFaction = "Horde" end
        
        if validFaction ~= "None" then
            table.insert(DP.EliteRoster, { 
                id = IDs[i], 
                name = Names[i], 
                rarity = rarity, 
                level = level, 
                zone = zone, 
                faction = validFaction 
            })
        end
    end
end